<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Folding Wooden Clothes Drying Rack</title>

  <style>
    :root {
      color-scheme: light;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
        "Segoe UI", sans-serif;
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background: #e8e3da;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      touch-action: none;
      cursor: grab;
    }

    canvas:active {
      cursor: grabbing;
    }

    .title-card {
      position: fixed;
      top: 24px;
      left: 24px;
      max-width: 340px;
      padding: 16px 18px;
      color: #392c22;
      background: rgba(250, 247, 240, 0.84);
      border: 1px solid rgba(78, 61, 45, 0.13);
      border-radius: 14px;
      box-shadow: 0 12px 35px rgba(61, 48, 34, 0.12);
      backdrop-filter: blur(12px);
      pointer-events: none;
    }

    .title-card h1 {
      margin: 0 0 5px;
      font-size: 19px;
      font-weight: 650;
      letter-spacing: 0.01em;
    }

    .title-card p {
      margin: 0;
      color: #746658;
      font-size: 12px;
      line-height: 1.5;
    }

    .controls {
      position: fixed;
      right: 22px;
      bottom: 22px;
      display: flex;
      flex-wrap: wrap;
      justify-content: flex-end;
      gap: 9px;
      max-width: calc(100vw - 44px);
    }

    button {
      appearance: none;
      padding: 10px 14px;
      color: #49382c;
      background: rgba(250, 247, 240, 0.9);
      border: 1px solid rgba(80, 65, 48, 0.16);
      border-radius: 10px;
      box-shadow: 0 8px 24px rgba(61, 48, 34, 0.1);
      font: inherit;
      font-size: 12px;
      font-weight: 600;
      cursor: pointer;
      backdrop-filter: blur(10px);
      transition:
        transform 150ms ease,
        background 150ms ease,
        box-shadow 150ms ease;
    }

    button:hover {
      transform: translateY(-1px);
      background: #fffdf7;
      box-shadow: 0 10px 28px rgba(61, 48, 34, 0.15);
    }

